//! Windowed todos — click a row to complete it, click × to delete it.
//! `run()` (generated by `libra::app!`) watches the view file in debug
//! builds, so editing todos.lx hot-reloads with your list preserved.

fn main() {
    if let Err(e) = todos::run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}
